529	
530	/** A digest with fewer entries than this is not worth an email. */
531	const MIN_ENTRIES = 1;
532	
533	/**
534	 * Collects one recipient's unread notifications inside the window. Returns
535	 * `null` — rather than an empty bundle — when the org's plan does not include
536	 * the digest, or when there is nothing to say: the caller treats `null` as
537	 * "send nothing", so a quiet day produces no mail at all.
538	 */
539	export async function buildDigest(
540	  orgId: OrgId,
541	  recipientId: UserId,
542	  windowStart: IsoTimestamp,
543	  windowEnd: IsoTimestamp,
544	): Promise<DigestBundle | null> {
545	  const org = await orgRepo.findOrgById(orgId);
546	  if (!org) return null;
547	
548	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
549	
550	  const unread = await notificationRepo.listUnreadSince(
551	    orgId,
552	    recipientId,
553	    windowStart,
554	  );
555	
556	  const entries: DigestEntry[] = unread
557	    .filter((notification) => notification.createdAt <= windowEnd)
558	    .map((notification) => ({
559	      notificationId: notification.id,
560	      kind: notification.kind,
561	      title: notification.title,
562	      href: notification.href,
563	      occurredAt: notification.createdAt,
564	    }))
565	    .slice(0, DIGEST_MAX_ENTRIES);
566	
567	  if (entries.length < MIN_ENTRIES) return null;
568	
569	  return { orgId, recipientId, entries, windowStart, windowEnd };
570	}
