718	/**
719	 * Publishes one `issue.overdue` per still-open, past-due issue. The job owns
720	 * no notification logic: it announces the fact, and whoever cares (in-app
721	 * alerts, the digest, webhooks) reacts on the bus.
722	 */
723	export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
724	  return runJob("overdue-issues", async (result) => {
725	    if (!shouldFilterArchived(LIVE_ONLY)) {
726	      logger.warn("archive scope misconfigured; skipping sweep", {});
727	      return;
728	    }
729	
730	    const stamp = toIsoTimestamp(now);
731	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
732	
733	    for (const orgId of orgIds) {
734	      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);
735	
736	      for (const issue of overdue) {
737	        if (issue.dueAt === null) continue;
738	        if (reported.has(issue.id)) continue;
739	
740	        try {
741	          await emit("issue.overdue", {
742	            orgId,
743	            actorId: null,
744	            occurredAt: stamp,
745	            issueId: issue.id,
746	            projectId: issue.projectId,
747	            dueAt: issue.dueAt,
748	            assigneeId: issue.assigneeId,
749	          });
750	          reported.add(issue.id);
751	          result.processed += 1;
752	        } catch (error) {
753	          result.failed += 1;
754	          logger.error("failed to announce overdue issue", {
755	            issueId: issue.id,
756	            reason: error instanceof Error ? error.message : String(error),
757	          });
758	        }
759	      }
760	    }
761	  });
762	}
