485	/**
486	 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
487	 *
488	 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
489	 */
490	import { subscribe } from "@/lib/event-bus";
491	import { createLogger } from "@/lib/logger";
492	import { enqueue } from "@/server/jobs/queue";
493	import { toIsoTimestamp } from "@/types/common";
494	import { registerActivityListeners } from "./activity-service";
495	import { registerSearchListeners } from "./search-service";
