500	/**
501	 * Importing this module also loads `notification-service` transitively, which
502	 * attaches the notification fan-out on first import — that hub has no
503	 * `register*` entry point of its own.
504	 */
505	import "./notification-service";
506	
507	const logger = createLogger("event-registry");
508	
509	/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
510	let detach: Unsubscribe | null = null;
511	
512	/**
513	 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
514	 * runs per server process, but a hot reload in dev can call it again and must
515	 * not double-deliver every event.
516	 */
517	export function registerEventHandlers(): void {
518	  if (detach !== null) return;
519	
520	  const offs: Unsubscribe[] = [
521	    registerActivityListeners(),
522	    registerSearchListeners(),
523	    registerUsageListeners(),
524	    registerWebhookListeners(),
525	    registerDigestBridge(),
526	  ];
527	
528	  detach = () => {
529	    for (const off of offs) off();
530	  };
531	
532	  logger.info("event handlers registered", { groups: offs.length });
533	}
534	
535	export function unregisterEventHandlers(): void {
536	  detach?.();
537	  detach = null;
538	}
