699	/**
700	 * The `organization_usage` counters read by every plan-limit check.
701	 */
702	import { and, count, eq, isNull, sql } from "drizzle-orm";
703	import {
704	  attachments,
705	  getDb,
706	  issues,
707	  members,
708	  organizationUsage,
709	  projects,
710	} from "@/server/db";
711	import { toIsoTimestamp } from "@/types/common";
712	import { toUsage } from "./_mappers";
713	import { brandId } from "./_mappers";
714	import type { OrgId } from "@/types/common";
715	import type { OrganizationUsage } from "@/types/organization";
716	
717	const BYTES_PER_MB = 1024 * 1024;
718	
719	/**
720	 * Reads the cached counters, materialising a zeroed row the first time an org
721	 * is asked about. A limit check must never fail because the rollup has not run.
722	 */
723	export async function getUsage(orgId: OrgId): Promise<OrganizationUsage> {
724	  const row = getDb()
725	    .select()
726	    .from(organizationUsage)
727	    .where(eq(organizationUsage.orgId, orgId))
728	    .get();
729	
730	  if (row) return toUsage(row);
731	
732	  const created = getDb()
733	    .insert(organizationUsage)
734	    .values({ orgId, measuredAt: toIsoTimestamp(new Date()) })
735	    .returning()
736	    .get();
737	
738	  return toUsage(created);
739	}
