799	/**
800	 * Cheap delta applied on the write path so a quota check right after a create
801	 * sees the new number without waiting for the rollup.
802	 */
803	export async function incrementUsage(
804	  orgId: OrgId,
805	  patch: Partial<
806	    Pick<
807	      OrganizationUsage,
808	      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
809	    >
810	  >,
811	): Promise<OrganizationUsage> {
812	  const current = await getUsage(orgId);
813	
814	  const row = getDb()
815	    .update(organizationUsage)
816	    .set({
817	      seatsUsed: current.seatsUsed + (patch.seatsUsed ?? 0),
