1063	/**
1064	 * Maps thrown domain errors onto `AppErrorShape`.
1065	 *
1066	 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
1067	 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
1068	 * `ZodError`); Server Actions and Route Handlers never propagate those to the
1069	 * client. Everything funnels through `toAppError()` so one thrown class maps
1070	 * to exactly one `ErrorCode` and one HTTP status, app-wide.
1071	 */
1072	import { FeatureDisabledError } from "@/lib/feature-flags";
1073	import { PermissionDeniedError } from "@/lib/permissions";
1074	import { InvalidSlugError } from "@/lib/slug";
1075	import { AlreadyArchivedError } from "@/lib/soft-delete";
1076	import { TenantScopeError } from "@/lib/tenant";
1077	import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
1078	import { ZodError, type ZodIssue } from "zod";
1079	
1080	export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
1081	  unauthorized: 401,
1082	  forbidden: 403,
1083	  not_found: 404,
1084	  validation_failed: 422,
1085	  conflict: 409,
1086	  rate_limited: 429,
1087	  plan_limit_exceeded: 402,
1088	  tenant_scope_violation: 403,
1089	  internal_error: 500,
1090	};
1091	
1092	/** True for the error classes this module knows how to translate faithfully. */
1093	export function isDomainError(error: unknown): boolean {
1094	  return (
1095	    error instanceof PermissionDeniedError ||
1096	    error instanceof TenantScopeError ||
1097	    error instanceof FeatureDisabledError ||
1098	    error instanceof AlreadyArchivedError ||
1099	    error instanceof InvalidSlugError ||
1100	    error instanceof ZodError
1101	  );
1102	}
1103	
1104	/** Collapses a `ZodError` into the `field → messages` map forms consume. */
1105	export function fieldErrorsFromZod(
1106	  error: ZodError,
1107	): Readonly<Record<string, readonly string[]>> {
1108	  const fields: Record<string, string[]> = {};
1109	  for (const issue of error.issues as readonly ZodIssue[]) {
1110	    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
1111	    (fields[key] ??= []).push(issue.message);
1112	  }
1113	  return fields;
1114	}
1115	
1116	export function toAppError(error: unknown): AppErrorShape {
1117	  if (error instanceof ZodError) {
1118	    return {
1119	      code: "validation_failed",
1120	      message: "Please correct the highlighted fields.",
1121	      fieldErrors: fieldErrorsFromZod(error),
1122	    };
1123	  }
1124	
1125	  if (error instanceof PermissionDeniedError) {
1126	    return {
1127	      code: "forbidden",
1128	      message: error.message,
1129	      meta: {
1130	        action: error.action,
1131	        resourceKind: error.decision.resourceKind,
1132	        reason: error.decision.reason,
1133	      },
1134	    };
1135	  }
1136	
1137	  if (error instanceof TenantScopeError) {
1138	    return {
1139	      code: "tenant_scope_violation",
1140	      message: "That resource belongs to a different organization.",
1141	      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
1142	    };
1143	  }
1144	
1145	  if (error instanceof FeatureDisabledError) {
1146	    return {
1147	      code: "forbidden",
1148	      message: error.message,
1149	      meta: { flag: error.flag },
1150	    };
1151	  }
1152	
1153	  if (error instanceof AlreadyArchivedError) {
1154	    return {
1155	      code: "conflict",
1156	      message: error.message,
1157	      meta: { entity: error.entity, id: error.id },
1158	    };
1159	  }
1160	
1161	  if (error instanceof InvalidSlugError) {
1162	    return {
1163	      code: "validation_failed",
1164	      message: error.message,
1165	      fieldErrors: { slug: [error.message] },
1166	      meta: { value: error.value },
1167	    };
1168	  }
1169	
1170	  return {
1171	    code: "internal_error",
1172	    message:
1173	      error instanceof Error ? error.message : "Something went wrong. Try again.",
1174	  };
1175	}
1176	
1177	/** The failure envelope a Server Action returns instead of throwing. */
1178	export function toActionResult(error: unknown): ActionResult<never> {
1179	  return {
1180	    ok: false,
1181	    error: toAppError(error),
1182	    submittedAt: new Date().toISOString(),
1183	  };
1184	}
