307	/**
308	 * Writes one notification row per recipient, each with the channel set that
309	 * recipient's preferences allow. A recipient who has muted every channel is
310	 * skipped entirely rather than given a row nobody will ever see.
311	 */
312	export async function notify(
313	  orgId: OrgId,
314	  kind: NotificationKind,
315	  recipients: readonly UserId[],
316	  payload: NotificationPayload,
317	): Promise<readonly Notification[]> {
318	  if (recipients.length === 0) return [];
319	
320	  const org = await orgRepo.findOrgById(orgId);
321	  const flags: FlagContext = {
322	    orgId,
323	    userId: payload.actorId,
324	    plan: org?.plan ?? "free",
325	    role: null,
326	    overrides: org?.settings.enabledFlagOverrides,
327	  };
328	
329	  const rows = [];
330	
331	  for (const recipientId of new Set(recipients)) {
332	    if (recipientId === payload.actorId) continue;
333	
334	    const preference = await preferenceRepo.getPreference(
335	      orgId,
336	      recipientId,
337	      kind,
338	    );
339	    const channels = resolveChannels(preference, flags);
340	    if (channels.length === 0) continue;
341	
342	    rows.push({
343	      orgId,
344	      recipientId,
345	      kind,
346	      title: payload.title,
347	      body: payload.body,
348	      href: payload.href,
349	      actorId: payload.actorId,
350	      channels,
351	    });
352	  }
353	
354	  return notificationRepo.insertNotifications(orgId, rows);
355	}
