572	/**
573	 * Who gets a digest: everyone who set at least one notification kind to
574	 * `digestOnly`. Opting into the digest is what suppresses the immediate
575	 * emails, so the two lists are two views of the same preference.
576	 */
577	export async function listDigestRecipients(
578	  orgId: OrgId,
579	): Promise<readonly UserId[]> {
