585	  bundle: DigestBundle,
586	  recipient: User,
587	): Promise<RenderedEmail> {
588	  return renderEmail("digest", {
589	    orgId: bundle.orgId,
590	    recipientName: recipient.name,
591	    entryCount: bundle.entries.length,
592	    windowStart: bundle.windowStart,
593	    windowEnd: bundle.windowEnd,
594	    headline: bundle.entries[0]?.title ?? "",
595	  });
596	}
597	/**
598	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
599	 *
600	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
601	 */
602	import { isEnabled } from "@/lib/feature-flags";
603	import { createLogger } from "@/lib/logger";
604	import * as notificationRepo from "@/server/repositories/notification-repository";
605	import * as orgRepo from "@/server/repositories/organization-repository";
606	import * as usageRepo from "@/server/repositories/usage-repository";
607	import * as userRepo from "@/server/repositories/user-repository";
608	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
609	import { sendEmail } from "@/server/services/email-service";
610	import { buildFlagContext } from "@/server/services/feature-flag-service";
611	import { toIsoTimestamp } from "@/types/common";
612	import { runJob } from "./types";
613	import type { JobResult } from "@/server/jobs/types";
614	import type { Organization } from "@/types/organization";
615	
616	const ORG_BATCH = 50;
617	const MS_PER_DAY = 24 * 60 * 60 * 1000;
618	
619	const logger = createLogger("digest-email-job");
620	
621	/**
622	 * One pass per scheduler tick. Each org is only processed during the UTC hour
623	 * it configured, so a tick that runs every few minutes still sends exactly one
624	 * digest per day per recipient.
625	 */
626	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
627	  return runJob("digest-email", async (result) => {
628	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
629	
630	    for (const orgId of orgIds) {
631	      const org = await orgRepo.findOrgById(orgId);
632	      if (!org || !shouldRunForOrg(org, now)) continue;
633	
634	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
635	
636	      const windowEnd = toIsoTimestamp(now);
637	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
638	
639	      for (const recipientId of await listDigestRecipients(orgId)) {
640	        try {
641	          const bundle = await buildDigest(
642	            orgId,
643	            recipientId,
644	            windowStart,
645	            windowEnd,
646	          );
647	          if (!bundle) continue;
648	
649	          const recipient = await userRepo.findUserById(recipientId);
650	          if (!recipient) continue;
651	
652	          const rendered = await renderDigest(bundle, recipient);
653	          await sendEmail({ to: recipient.email, ...rendered });
654	
655	          // Once digested, these notifications are no longer "unread" — this
656	          // is what keeps a later run inside the same window from sending
657	          // the same digest twice.
658	          for (const entry of bundle.entries) {
659	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
660	          }
661	
662	          result.processed += 1;
663	        } catch (error) {
664	          result.failed += 1;
665	          logger.error("digest failed", {
666	            orgId,
667	            recipientId,
668	            reason: error instanceof Error ? error.message : String(error),
669	          });
670	        }
671	      }
672	    }
673	  });
674	}
