676	/**
677	 * True during the org's configured digest hour. Exported because the schedule
678	 * decision is worth testing on its own, without a database.
679	 */
680	export function shouldRunForOrg(org: Organization, now: Date): boolean {
681	  if (org.archivedAt !== null) return false;
682	  return now.getUTCHours() === org.settings.digestHourUtc;
683	}
684	/**
685	 * Scans for issues past `dueAt` and emits `issue.overdue`, which the notification fan-out turns into alerts.
686	 *
687	 * Must call (do not reimplement): emit, shouldFilterArchived
688	 */
689	import { emit } from "@/lib/event-bus";
690	import { createLogger } from "@/lib/logger";
691	import { shouldFilterArchived } from "@/lib/soft-delete";
692	import * as issueRepo from "@/server/repositories/issue-repository";
693	import * as usageRepo from "@/server/repositories/usage-repository";
694	import { toIsoTimestamp } from "@/types/common";
695	import { runJob } from "./types";
696	import type { JobResult } from "@/server/jobs/types";
697	
698	/** How many organizations one pass sweeps. */
699	const ORG_BATCH = 50;
700	
701	/** Archived issues are never overdue — an archived issue has no due date. */
702	const LIVE_ONLY = {} as const;
703	
704	const logger = createLogger("overdue-issue-job");
705	
706	/**
707	 * Issues already announced this process's lifetime. A later sweep still
708	 * finds a still-open, still-overdue issue — this is what keeps the job from
709	 * re-emitting `issue.overdue` for it on every pass.
710	 */
711	const reported = new Set<string>();
712	
713	/** Test-only: clears the reported set so a fresh scenario starts empty. */
714	export function resetOverdueTracking(): void {
715	  reported.clear();
716	}
