790	/**
791	 * Full recount from the source tables. Called by the rollup job and by every
792	 * event that could have moved a counter — after recounting, the seat and
793	 * project totals are checked against the plan so a breach surfaces as an
794	 * event rather than waiting for the next write to be rejected.
795	 */
796	export async function recomputeUsage(
797	  orgId: OrgId,
798	): Promise<OrganizationUsage> {
799	  const usage = await usageRepo.recomputeUsage(orgId);
800	  const org = await orgRepo.findOrgById(orgId);
801	  if (!org) return usage;
802	
803	  const limits = getPlanLimits(org.plan);
804	
805	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
806	    await emit("billing.limit_exceeded", {
807	      orgId,
808	      actorId: null,
809	      occurredAt: toIsoTimestamp(new Date()),
810	      resource: "seats",
811	      limit: limits.seats,
812	      used: usage.seatsUsed,
