1054	/**
1055	 * Extracts `@handle` mentions from comment bodies and resolves them to member
1056	 * ids.
1057	 *
1058	 * A handle is the local part of a member's email address, lowercased — that
1059	 * is what the comment composer autocompletes and what `CommentService` feeds
1060	 * to the notification fan-out, so extraction and resolution must agree
1061	 * exactly. Mentions inside code spans and fenced blocks are ignored.
1062	 */
1063	import type { UserId } from "@/types/common";
1064	import type { MemberWithUser } from "@/types/member";
1065	
1066	/** `@` must start the line or follow whitespace/punctuation, never an email. */
1067	const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;
1068	
1069	function withoutCode(body: string): string {
1070	  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
1071	}
1072	
1073	/** The handle Taskflow addresses a member by, derived from their email. */
1074	export function handleOf(member: MemberWithUser): string {
1075	  return (member.user.email.split("@")[0] ?? "").toLowerCase();
1076	}
1077	
1078	/** Every distinct handle mentioned, in first-appearance order. */
1079	export function extractMentions(body: string): readonly string[] {
1080	  const seen = new Set<string>();
1081	  const handles: string[] = [];
1082	
1083	  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
1084	    const handle = (match[2] ?? "").toLowerCase();
1085	    if (handle === "" || seen.has(handle)) continue;
1086	    seen.add(handle);
1087	    handles.push(handle);
1088	  }
1089	
1090	  return handles;
1091	}
