1093	/**
1094	 * Maps the mentions in `body` onto the ids of members who actually exist in
1095	 * the organization. Unknown handles are silently dropped — a typo must never
1096	 * fail the comment write.
1097	 */
1098	export function resolveMentions(
1099	  body: string,
1100	  members: readonly MemberWithUser[],
1101	): readonly UserId[] {
1102	  const byHandle = new Map<string, UserId>();
1103	  for (const member of members) {
1104	    byHandle.set(handleOf(member), member.userId);
1105	  }
1106	
1107	  const resolved: UserId[] = [];
1108	  const seen = new Set<UserId>();
1109	  for (const handle of extractMentions(body)) {
1110	    const userId = byHandle.get(handle);
1111	    if (userId === undefined || seen.has(userId)) continue;
1112	    seen.add(userId);
1113	    resolved.push(userId);
1114	  }
1115	
1116	  return resolved;
1117	}
