314	/**
315	 * Creates a project once the plan still has room for one. The key is derived
316	 * from the name when the caller left it blank, so the issue numbering scheme
317	 * (`TF-12`) is never invented at the call site.
318	 */
319	export async function createProject(
320	  actor: Actor,
321	  input: CreateProjectInput,
322	): Promise<Project> {
323	  assertOrgScope(actor, input.orgId);
324	  assertCan(actor, "project:create", orgResource(input.orgId));
325	
326	  const org = requireFound(
327	    await orgRepo.findOrgById(input.orgId),
328	    "Organization",
329	    input.orgId,
330	  );
331	
332	  const used = await projectRepo.countProjects(input.orgId);
333	  if (wouldExceedLimit(org.plan, "projects", used)) {
334	    throw new Error(
335	      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
336	    );
337	  }
338	
339	  const slug = await suggestProjectSlug(input.orgId, input.name);
340	
341	  const project = await projectRepo.insertProject({
342	    ...input,
343	    slug,
344	    key: input.key || projectKeyFromName(input.name),
345	  });
346	
347	  await emit("project.created", {
348	    ...actorEnvelope(actor),
349	    projectId: project.id,
350	    name: project.name,
351	    slug: project.slug,
352	  });
353	
354	  return project;
355	}
