540	/**
541	 * The one piece of wiring that belongs to no single service: turning a
542	 * `digest.due` event into a queued job. Keeping it here rather than inside
543	 * `DigestService` stops the service layer from depending on the job layer.
544	 */
545	function registerDigestBridge(): Unsubscribe {
546	  return subscribe("digest.due", (payload) => {
547	    enqueue({
548	      id: `digest:${payload.orgId}:${payload.recipientId}`,
549	      kind: "digest-email",
550	      runAt: toIsoTimestamp(new Date()),
551	      attempts: 0,
552	      payload: {
553	        orgId: payload.orgId,
554	        recipientId: payload.recipientId,
555	        windowStart: payload.windowStart,
556	      },
557	    });
558	  });
559	}
