741	/**
742	 * Recounts every dimension from the source tables and rewrites the cache.
743	 * Called by the rollup job and after any bulk change that would drift.
744	 */
745	export async function recomputeUsage(
746	  orgId: OrgId,
747	): Promise<OrganizationUsage> {
748	  const db = getDb();
749	
750	  const seats = db
751	    .select({ value: count() })
752	    .from(members)
753	    .where(
754	      and(
755	        eq(members.orgId, orgId),
756	        eq(members.status, "active"),
757	        isNull(members.archivedAt),
758	      ),
759	    )
760	    .get();
761	
762	  const projectCount = db
763	    .select({ value: count() })
764	    .from(projects)
765	    .where(and(eq(projects.orgId, orgId), isNull(projects.archivedAt)))
766	    .get();
767	
768	  const issueCount = db
769	    .select({ value: count() })
770	    .from(issues)
771	    .where(and(eq(issues.orgId, orgId), isNull(issues.archivedAt)))
772	    .get();
773	
774	  const bytes = db
775	    .select({ value: sql<number | null>`sum(${attachments.sizeBytes})` })
776	    .from(attachments)
777	    .where(eq(attachments.orgId, orgId))
778	    .get();
779	
780	  const next = {
781	    orgId,
782	    seatsUsed: seats?.value ?? 0,
783	    projectsUsed: projectCount?.value ?? 0,
784	    issuesUsed: issueCount?.value ?? 0,
785	    storageMbUsed: Math.ceil((bytes?.value ?? 0) / BYTES_PER_MB),
786	    measuredAt: toIsoTimestamp(new Date()),
787	  };
788	
789	  const row = db
790	    .insert(organizationUsage)
791	    .values(next)
792	    .onConflictDoUpdate({ target: organizationUsage.orgId, set: next })
793	    .returning()
794	    .get();
795	
796	  return toUsage(row);
797	}
