sub(p,'''export async function findMemberById(''','''/**
 * The current membership of `userId` in `orgId`, or `null` when there is none
 * or it has ended. This is the lookup for "may this person act here / be
 * assigned work / be notified" — a removed member never comes back from it.
 */
export async function findCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

/** The subset of `userIds` that are current members of `orgId`. */
export async function filterCurrentMemberUserIds(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<ReadonlySet<UserId>> {
  const unique = [...new Set(userIds)];
  if (unique.length === 0) return new Set();

  const rows = getDb()
    .select({ userId: members.userId })
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        inArray(members.userId, unique),
        liveMemberPredicate(),
      ),
    )
    .all();

  return new Set(rows.map((row) => row.userId as UserId));
}

